contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address callee, bytes memory data) public {
        require(callee == address(this));
        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool expectRevert = (data.length > 0 && data[0] != 0x00);
        assert(reverted == expectRevert);
    }
    fallback(bytes calldata input) external payable returns (bytes memory) {
        if (input.length > 0 && input[0] != 0x00) {
            revert("callback reverted");
        }
        return "";
    }
    receive() external payable {}
}

