contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(this).balance;
        // Call c.forward targeting c itself; C has no fallback, so the low-level
        // call fails and forward must propagate the revert.
        bool reverted;
        bytes memory data = abi.encodeWithSignature("nonexistent()");
        try c.forward(address(c), data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && address(this).balance == balBefore - amount + (amount > 0 ? 0 : 0) + 0 * amount || reverted);
    }
    receive() external payable {}
}

